function preloadDiaryNext(){if(location.hash!=='#album')return;const p=C.photos[diaryIndex+1];if(p){const next=new Image();next.decoding='async';next.src=p.src}}
const C=window.CONTENT,main=document.querySelector('main'),modal=document.querySelector('dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',timeZone:'Europe/Istanbul'}).format(new Date(d));
function getSimulatedStart(){return window.SIMULATED_START_DATE||C.startDate}
function getSimulatedNow(){return window.SIMULATED_DATE?+new Date(window.SIMULATED_DATE):Date.now()}
function release(i){const s=getSimulatedStart();if(!s)return null;return new Date(+new Date(s)+(+new Date(C.finalDate)-+new Date(s))*i/14)}
function unlocked(i){if(window.ADMIN_UNLOCKED)return true;const s=getSimulatedStart();return Boolean(s&&getSimulatedNow()>=+release(i))}
function home(){return `<section class="hero"><div class="hero-text"><span class="eyebrow">Sadece ikimize ait bir yer</span><h1>Biraz sen,<br>biraz ben,<br><em>bir dolu biz.</em></h1><p>En sevdiğim hikâye, seninle olanı.<br>Anılarımızı, küçük mutluluklarımızı ve henüz yazılmamış sayfalarımızı buraya sakladım.</p><div class="actions"><a class="btn" href="#story">Hikâyemize göz at <span>↗</span></a><a class="btn secondary" href="#album">Anılara dal ♡</a></div><span class="small-note">psst… burada küçük sürprizler saklı.</span></div><div class="hero-art"><div><img fetchpriority="high" decoding="async" src="assets/rabbits-meadow.webp" alt="Papatya tarlasında yıldızları izleyen iki minik tavşan"><div class="art-caption">aynı gökyüzünün altında, hep yan yana.</div></div><div class="tiny-note">en sevdiğim yer:<br>senin yanın ♡</div></div></section><div class="divider" aria-hidden="true">✧ ♡ ✧</div><div class="section-head"><div><span class="eyebrow">Bugün nereye gidelim?</span><h2>Küçük dünyamızın köşeleri</h2></div></div><section class="tiles"><a class="tile" href="#story"><span class="symbol">✦</span><span class="corner">15 bölüm ↗</span><h3>Bizim çizgi romanımız</h3><p>Her yeni sayfada, biraz daha biz.</p></a><a class="tile" href="#album"><span class="symbol">♡</span><span class="corner">Anı kutusu ↗</span><h3>İyi ki bu anlar var</h3><p>Bir fotoğraf, bin güzel his.</p></a><button class="tile" id="letter" style="text-align:left;color:inherit"><span class="symbol">✉</span><span class="corner">Sana özel ↗</span><h3>Bir küçük not bıraktım</h3><p>Açmak için kalbine dokunman yeter.</p></button></section><div class="news-banner" style="margin-top:22px;background:linear-gradient(135deg,#fdf5f9,#f7eff9);border:1px solid #ebd9e8;border-radius:15px;padding:18px 25px;display:flex;justify-content:space-between;align-items:center;gap:15px;"><div style="display:flex;align-items:center;gap:12px;"><span style="font-size:24px">📢</span><div><strong style="font-size:15px;display:block;color:var(--ink)">Evrenden Havadisler & Yenilikler</strong><span style="font-size:13px;color:#8d748c">Sitemize eklenen yeni anılar, sürprizler ve güncellemeler panosu.</span></div></div><a class="btn secondary" href="#news" style="padding:8px 16px;font-size:13px;">Havadislere Bak ↗</a></div><div class="banner"><div><strong>En güzel sayfayı sona sakladım ♡</strong><p>${getSimulatedStart()?'Hikâyemiz başladı. Her bölüm kendi gününde açılacak.':'Hikâyemiz hazırlanıyor. İlk sayfayla birlikte yolculuğumuz başlayacak.'}</p></div><div class="date">3 Kasım 2026<small>Final bölümümüz</small></div></div>`}
function story(){return `<div class="page-heading"><span class="eyebrow">Başrolünde sen ve ben</span><h1>Bizim <em>hikâyemiz.</em></h1><p>On beş bölüm, bir minik evren. ${getSimulatedStart()?'Yeni sayfalar kendi gününde açılır.':'İlk sayfalar hazırlanıyor; yolculuğumuz yakında başlayacak.'}</p></div><section class="chapters" aria-label="Çizgi roman bölümleri">${Array.from({length:15},(_,i)=>{const chapter=C.chapters[i],ready=chapter?.pages?.length;return `<button class="chapter" data-chapter="${i}"><div class="cover"><span>${unlocked(i)&&ready?'♡':'♧'}</span><b>${String(i+1).padStart(2,'0')}</b><span>${i===14?'Büyük final':'Bizim hikâyemiz'}</span></div><div class="chapter-info"><strong>${i===14?'15. Bölüm · Final':`${i+1}. Bölüm`}</strong><small>${!getSimulatedStart()?(i===14?'3 Kasım · Final':'Yakında'):!unlocked(i)?fmt(release(i))+' · Kilitli':ready?'Okumaya hazır ♡':'Sayfaları hazırlanıyor'}</small></div></button>`}).join('')}</section><div class="banner"><p>Her hikâyenin bir zamanı var. Bizimkinin en güzel sonu da 3 Kasım’da.</p><span>♡</span></div>`}
function photoDate(p){return p.date?new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'}).format(new Date(p.date+'T12:00:00+03:00')):''}
let diaryIndex=0;
function diaryPage(){const p=C.photos[diaryIndex];if(!p)return '';return `<div class="diary-date"><time>${esc(photoDate(p))||'Kalbimizde kalan bir gün'}</time><span>sevgili günlük…</span></div><button class="diary-photo" data-photo="${diaryIndex}" aria-label="Bu fotoğrafı büyüt"><img src="${esc(p.src)}" alt="Günlüğümüzün ${diaryIndex+1}. fotoğrafı" decoding="async"><small>bir anı, bin güzel his ♡ · büyütmek için dokun</small></button><p class="diary-note">${esc(p.caption)} ♡</p><p class="diary-sign">sen + ben</p>`}
function album(){return `<div class="page-heading diary-heading"><span class="eyebrow">Sadece bize ait sayfalar</span><h1>Bizim <em>anı günlüğümüz.</em></h1><p>Her sayfada biraz daha biz.</p></div>${C.photos.length?`<section class="diary-book" aria-label="Anı günlüğümüz"><article class="diary-sheet">${diaryPage()}</article></section><nav class="diary-controls" aria-label="Günlük sayfaları"><button data-diary-step="-1" ${diaryIndex===0?'disabled':''}>← Önceki sayfa</button><span class="diary-count" role="status" aria-live="polite">${diaryIndex+1} / ${C.photos.length}<small>günlüğümüzün sayfaları</small></span><button data-diary-step="1" ${diaryIndex===C.photos.length-1?'disabled':''}>Sonraki sayfa →</button></nav><p class="diary-hint">Sayfaları ok tuşlarıyla ya da telefonda yana kaydırarak çevirebilirsin.</p>`:'<div class="empty-album"><h2>İlk anımızı bekliyoruz ♡</h2></div>'}`}
let currentPhoto=null;
function openPhoto(i){currentPhoto=(i+C.photos.length)%C.photos.length;const p=C.photos[currentPhoto];const html=`<div class="photo-viewer"><img src="${esc(p.src)}" alt="Anı albümümüzden ${currentPhoto+1}. fotoğraf"><p class="photo-note">${esc(p.caption)} ♡</p><small>${esc(photoDate(p))}</small><div class="photo-controls"><button class="btn secondary" data-step="-1" aria-label="Önceki fotoğraf">← Önceki</button><span aria-live="polite">${currentPhoto+1} / ${C.photos.length}</span><button class="btn secondary" data-step="1" aria-label="Sonraki fotoğraf">Sonraki →</button></div></div>`;if(modal.open)document.querySelector('#modal-content').innerHTML=html;else show(html)}
document.addEventListener('keydown',e=>{if(!modal.open||currentPhoto===null)return;if(e.key==='ArrowLeft'){e.preventDefault();openPhoto(currentPhoto-1)}if(e.key==='ArrowRight'){e.preventDefault();openPhoto(currentPhoto+1)}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-step]');if(b&&currentPhoto!==null)openPhoto(currentPhoto+Number(b.dataset.step))});
modal.addEventListener('close',()=>{currentPhoto=null;modal.querySelectorAll('video').forEach(v=>v.pause())});
function render(){let page=location.hash.slice(1)||'home';if(page==='admin'){if(window.ADMIN_AUTHENTICATED){if(typeof openAdminPanel==='function')openAdminPanel()}else{if(typeof openAdminLogin==='function')openAdminLogin()}page='home'}if(page==='stickers'&&!stickerGiftAvailable())page='home';if(page==='magic'&&!magicAvailable())page='home';document.body.dataset.page=page;main.innerHTML=page==='story'?story()+storyGift():page==='album'?album()+memoryInvitation():page==='magic'?magic():page==='stickers'?stickers():page==='news'?(typeof news==='function'?news():''):home()+memoryInvitation();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));window.scrollTo(0,0);syncStickerGift();syncMagicMemories();mountMagicalMemories();if(page==='album')preloadDiaryNext()}
function show(html){document.querySelector('#modal-content').innerHTML=html;modal.showModal()}
function note(){show(`<div class="message"><span class="eyebrow">Sana bir küçük not</span><h2>İyi ki yollarımız<br><em>birbirine çıktı.</em></h2><p>Bu küçük evrendeki her şey, yüzünde bir gülümseme görmek için.<br><br>Birlikte biriktirdiğimiz anılar ve bizi bekleyen bütün güzel günler için…<br><br>Bu hikâyenin en sevdiğim kahramanı sensin.</p><span>♡</span></div>`)}
function hearts(x=innerWidth/2,y=innerHeight/2){for(let i=0;i<12;i++){let e=document.createElement('span');e.className='particle';e.textContent=['♡','✧','🌼'][i%3];e.style.cssText=`left:${x}px;top:${y}px;color:#df7caa;--dx:${(Math.random()-.5)*260}px`;document.body.appendChild(e);setTimeout(()=>e.remove(),1600)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='letter')note();if(b.classList.contains('heart-button')){hearts(e.clientX,e.clientY);const t=document.querySelector('#toast');t.textContent='Biraz daha sevgi, sırf senin için ♡';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}if(b.id==='surprise'){hearts();show('<span style="font-size:55px">🌼</span><h2>Bir papatya tuttum senin için.</h2><p>Son yaprağında da aynı şey yazıyor:<br><strong>Çok seviyor. ♡</strong></p>')}if(b.dataset.chapter!==undefined){const i=+b.dataset.chapter,chapter=C.chapters[i];if(!getSimulatedStart()&&!window.ADMIN_UNLOCKED)show('<h2>İlk sayfamız henüz yazılıyor ♡</h2><p>Hikâyemiz hazır olduğunda bölüm takvimi başlayacak.<br>Finalimiz 3 Kasım’da.</p>');else if(!unlocked(i))show(`<h2>Biraz merak güzel şey…</h2><p>${i+1}. bölüm ${fmt(release(i))} tarihinde açılacak. ♡</p>`);else if(!chapter?.pages?.length)show(`<h2>${i+1}. Bölüm</h2><p>${window.ADMIN_UNLOCKED?'Admin önizlemesi: Bu bölümün resimleri henüz eklenmemiş.':'Bu bölümün sayfaları hazırlanıyor. Çok yakında burada buluşacağız. ♡'}</p>`);else show(`<div class="reader"><h2>${i+1}. Bölüm</h2>${chapter.pages.map((p,j)=>`<img src="${esc(p)}" alt="${i+1}. bölüm, ${j+1}. sayfa">`).join('')}<button class="btn" id="read-done">Okudum ♡</button></div>`)}if(b.dataset.photo!==undefined)openPhoto(+b.dataset.photo);if(b.id==='read-done'){modal.close();hearts()}if(b.classList.contains('close'))modal.close()});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});window.addEventListener('hashchange',render);render();setInterval(()=>{const sNav=document.querySelector('[data-page="stickers"]'),mNav=document.querySelector('[data-page="magic"]');if(!modal.open&&(location.hash==='#story'||(sNav&&sNav.hidden===stickerGiftAvailable())||(mNav&&mNav.hidden===magicAvailable())))render()},60000);


